import{B as e,Lt as t,Z as n,et as r,mt as i,nt as a,tt as o}from"./chunks/framework.CxxritPY.js";import"./chunks/assets.B3YjwfWu.js";var s=JSON.parse(`{"title":"고객사 테스트 서버 관리하기","description":"최근 이어지는 취약점 공개에 대한 부담을 줄이기 위해 AWS SSM Patch Manager로 고객사 AlmaLinux 테스트 서버를 관리하는 기준을 정리한다.","frontmatter":{"title":"고객사 테스트 서버 관리하기","date":"2026-11-19T07:00+09:00","description":"최근 이어지는 취약점 공개에 대한 부담을 줄이기 위해 AWS SSM Patch Manager로 고객사 AlmaLinux 테스트 서버를 관리하는 기준을 정리한다.","tags":["Linux","AlmaLinux","AWS","SSM"]},"headers":[],"relativePath":"posts/aws-ssm-patch-manager.md","filePath":"posts/aws-ssm-patch-manager.md","lastUpdated":1795523607000}`),c={name:`posts/aws-ssm-patch-manager.md`},l={id:`frontmatter-title`,tabindex:`-1`};function u(e,s,c,u,d,f){return i(),r(`div`,null,[n(`h1`,l,[a(t(e.$frontmatter.title)+` `,1),s[0]||=n(`a`,{class:`header-anchor`,href:`#frontmatter-title`,"aria-label":`Permalink to “{{ $frontmatter.title }}”`},`​`,-1)]),s[1]||=o(`<p>최근 주요 보안 취약점이 연달아 공개되고 있다.</p><ul><li><a href="/posts/linux-kernel-tcp">리눅스 커널 TCP 원격 코드 실행 취약점</a> (<code>CVE-2026-98432</code>)</li><li>OpenJDK 원격 코드 실행 취약점 <a href="https://news.hada.io/topic?id=37370" target="_blank" rel="noreferrer">Java4Shell</a> (<code>CVE-2026-114938</code>)</li><li>NGINX에서 커널 권한 상승까지 이어지는 <a href="https://news.hada.io/topic?id=37417" target="_blank" rel="noreferrer">NGINX2Root</a></li></ul><p>이제는 애플리케이션을 넘어 웹 서버·런타임·OS 커널까지 전담 인프라 담당자 없이는 제때 대응하기 버겁다.</p><p>이에 따라 그동안 미뤄 두었던 고객사 EC2 테스트 환경의 커널 패치도 자동 관리하기로 했다.</p><h2 id="최근-almalinux-주요-커널-cve-현황" tabindex="-1">최근 AlmaLinux 주요 커널 CVE 현황 <a class="header-anchor" href="#최근-almalinux-주요-커널-cve-현황" aria-label="Permalink to “최근 AlmaLinux 주요 커널 CVE 현황”">​</a></h2><p><a href="https://almalinux.org/security/" target="_blank" rel="noreferrer">AlmaLinux 보안 페이지</a>를 보면, 알게 모르게 최근 몇 주 사이에도 치명적(Critical)이거나 중요(Important) 등급의 리눅스 커널 패치가 연이어 올라와 있었다.</p><table tabindex="0"><thead><tr><th>CVE 번호</th><th>심각도</th><th>주요 영향 및 내용</th></tr></thead><tbody><tr><td><a href="https://almalinux.org/blog/2026-10-16-pwnescape-cve-2026-99999/" target="_blank" rel="noreferrer"><code>CVE-2026-99999</code></a> (PwnEscape)</td><td>Critical (9.3)</td><td><code>virtio-net</code>/TAP 체크섬 오프로드 처리 결함으로 게스트-호스트 VM 탈출 및 원격 코드 실행 위험</td></tr><tr><td><a href="https://almalinux.org/blog/2026-10-30-cve-2026-98432/" target="_blank" rel="noreferrer"><code>CVE-2026-98432</code></a></td><td>Critical (9.8)</td><td>IPv4 TCP 연결 처리 중 Use-After-Free (원격 코드 실행·커널 패닉 위험)</td></tr><tr><td><a href="https://almalinux.org/blog/2026-11-06-cve-2026-98276/" target="_blank" rel="noreferrer"><code>CVE-2026-98276</code></a></td><td>High (7.8)</td><td><code>sock_gettstamp()</code>와 UDP <code>bind()</code> 경합으로 인한 Use-After-Free (로컬 권한 상승·커널 패닉)</td></tr><tr><td><a href="https://almalinux.org/blog/2026-11-16-noisytcp-cve-2026-99288/" target="_blank" rel="noreferrer"><code>CVE-2026-99288</code></a> (NoisyTCP)</td><td>Important (7.5)</td><td>TCP 소켓 조회(<code>ehash</code>) 경합으로 인한 NULL 포인터 역참조 및 원격 커널 패닉</td></tr></tbody></table><p>원래 테스트 서버는 고객사 요청이 있을 때 운영 환경보다 먼저 업데이트를 시도해 보려고 만들어 둔 환경이라, 별도 요청이 없다면 대응하지 않고 있었다. 하지만 최근 리눅스 커널 취약점이 잇따라 공개되는데도 고객사에서 연락이 없는 걸 보면, 고객사 측에서도 인프라 관리를 제대로 챙기지 못하는 듯하다.</p><p>이제는 고객사 요청이 없더라도 테스트 서버 역시 운영 환경과 같은 수준으로 미리 커널 패치를 챙겨 두어야 한다.</p><h2 id="일반적인-수동-커널-패치-명령어" tabindex="-1">일반적인 수동 커널 패치 명령어 <a class="header-anchor" href="#일반적인-수동-커널-패치-명령어" aria-label="Permalink to “일반적인 수동 커널 패치 명령어”">​</a></h2><p>원래는 EC2 인스턴스에 직접 접속해서 <code>dnf</code> 명령어로 커널을 업데이트하고 재부팅한다.</p><div class="vp-code-block-title"><div class="vp-code-block-title-bar"><span class="vp-code-block-title-text" data-title="AlmaLinux 커널 수동 패치 및 확인">AlmaLinux 커널 수동 패치 및 확인</span></div><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 1. 현재 실행 중인 커널 버전 확인</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 2. DNF 메타데이터 캐시 초기화 및 커널 패키지 업그레이드</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dnf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> metadata</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dnf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kernel</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 3. 재부팅 필요 여부 확인 (dnf-utils 설치 시)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> needs-restarting</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 4. 새 커널 반영을 위한 서버 재부팅</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span></code></pre></div></div><p>재부팅이 끝나면 다시 <code>uname -r</code> 명령어로 올라간 커널 버전을 확인한다.</p><h2 id="kernel-live-patching-on-al2023" tabindex="-1">Kernel Live Patching on AL2023 <a class="header-anchor" href="#kernel-live-patching-on-al2023" aria-label="Permalink to “Kernel Live Patching on AL2023”">​</a></h2><p>AL2023 문서를 찾아보다 새로 알게 된 사실인데, 조직 표준인 Amazon Linux 2023(AL2023)은 추가 비용 없이 <a href="https://docs.aws.amazon.com/linux/al2023/ug/live-patching.html" target="_blank" rel="noreferrer">Kernel Live Patching</a>을 지원한다. DNF나 SSM으로 <code>kernel-livepatch</code> RPM 패키지를 배포하면 서버를 재부팅하지 않고도 실행 중인 커널에 주요 CVE 패치를 적용할 수 있다. 다만 커널 버전마다 릴리즈 후 3개월까지만 라이브 패치가 제공되므로, 그 이후에는 커널을 직접 업그레이드해야 한다.</p><p>반면 고객사 환경의 AlmaLinux 같은 구독형(AWS Marketplace) AMI는 SSM Patch Manager에서 커널 라이브 패칭을 기본 지원하지 않는다. 새 커널을 설치해도 디스크에만 저장되므로, 실행 중인 커널에 패치를 반영하려면 <strong>서버 재부팅</strong> 이 필수다.</p><h2 id="ssm-patch-manager로-정기-패치-자동화" tabindex="-1">SSM Patch Manager로 정기 패치 자동화 <a class="header-anchor" href="#ssm-patch-manager로-정기-패치-자동화" aria-label="Permalink to “SSM Patch Manager로 정기 패치 자동화”">​</a></h2><p>최근 인프라 설정을 따로 검토하지 않고 있었는데, AWS SSM 기능 중에 Patch Manager가 눈에 들어왔다. EC2에 <code>amazon-ssm-agent</code>와 IAM 역할을 연결해 Patch Manager로 패치와 재부팅을 일괄 관리하기로 했다.</p><h3 id="amazonssmmanagedinstancecore" tabindex="-1">AmazonSSMManagedInstanceCore <a class="header-anchor" href="#amazonssmmanagedinstancecore" aria-label="Permalink to “AmazonSSMManagedInstanceCore”">​</a></h3><p>SSM Patch Manager를 사용하려면 인스턴스 프로파일에 <code>AmazonSSMManagedInstanceCore</code> 정책이 필요하다. 기존 조직에서 쓰던 <code>AmazonEC2RoleforSSM</code>은 AWS가 지원을 중단한 오래된 정책이므로 이번 작업과 함께 새로운 정책으로 전환한다. 다만 <code>AmazonSSMManagedInstanceCore</code>에는 일반 S3 접근 권한이 빠져 있다. 패치 실행 로그나 결과를 S3 버킷에 저장하려면, 인스턴스 역할에 대상 S3 버킷에 대한 읽기·쓰기(<code>s3:GetObject</code>, <code>s3:PutObject</code> 등) 권한을 별도로 추가해야 한다.</p><div class="tip custom-block"><p class="custom-block-title">Agent Toolkit for AWS</p><p>회사 맥북 장비에는 이미 <a href="https://github.com/aws/agent-toolkit-for-aws" target="_blank" rel="noreferrer">Agent Toolkit for AWS</a>(<a href="https://raw.githubusercontent.com/aws/agent-toolkit-for-aws/refs/heads/main/setup-instructions/setup.md" target="_blank" rel="noreferrer">설치 안내</a>)가 설치되어 있어요. AI 코딩 에이전트에 AWS MCP 서버와 스킬이 연동되어 있으니, 에이전트가 현재 AWS 환경을 조회해 사전 조사를 수행하고 Patch Manager 도입 계획을 세운 뒤 IAM 정책, S3 버킷, 알림 설정까지 저 대신 알아서 처리해 줄 거예요.</p></div><h3 id="패치-베이스라인" tabindex="-1">패치 베이스라인 <a class="header-anchor" href="#패치-베이스라인" aria-label="Permalink to “패치 베이스라인”">​</a></h3><p>AWS는 AlmaLinux용 기본 베이스라인 <code>AWS-AlmaLinuxDefaultPatchBaseline</code>을 제공한다. 하지만 테스트 서버에서 운영하는 JDK, Redis, Elasticsearch에 맞춰 승인 대기 기간(<code>ApproveAfterDays</code>)과 패키지 포함·제외 조건을 관리하기 위해 자체 기준선(Custom Patch Baseline)을 만들어 대상 서버 태그(예: <code>PatchGroup: customer-test</code>)에 연결하기로 했다.</p><p>Patch Manager는 커널뿐 아니라 <code>dnf</code> 저장소의 미들웨어·런타임 패키지도 함께 업데이트한다. 이에 따라 Elasticsearch는 내장 JDK 대신 시스템 JDK를 사용하도록 전환해 JDK 보안 패치까지 함께 관리하고, 취약점이 자주 보고되는 Redis 역시 패치 제외 대상에 넣지 않고 업데이트 범위에 포함했다.</p><h3 id="유지-관리-기간" tabindex="-1">유지 관리 기간 <a class="header-anchor" href="#유지-관리-기간" aria-label="Permalink to “유지 관리 기간”">​</a></h3><p>정기 패치는 유지 관리 기간(Maintenance Window)에 <code>AWS-RunPatchBaseline</code> 문서를 <code>Operation: Install</code>로 실행하도록 등록한다. AlmaLinux 커널 패치 반영에는 재부팅이 필요하므로 <code>RebootOption</code>은 기본값(<code>RebootIfNeeded</code>)을 유지한다.</p><h3 id="aws-runpatchbaseline" tabindex="-1">AWS-RunPatchBaseline <a class="header-anchor" href="#aws-runpatchbaseline" aria-label="Permalink to “AWS-RunPatchBaseline”">​</a></h3><p>Patch Manager를 설정했다면 긴급 취약점 대응이나 동작 검증 시에도 직접 EC2 인스턴스에서 명령어를 실행하지 않고, SSM Run Command에서 <code>AWS-RunPatchBaseline</code>을 수동 실행한다.</p><div class="vp-code-block-title"><div class="vp-code-block-title-bar"><span class="vp-code-block-title-text" data-title="AWS CLI로 AWS-RunPatchBaseline 수동 실행">AWS CLI로 AWS-RunPatchBaseline 수동 실행</span></div><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 점검</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aws</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> send-command</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --document-name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;AWS-RunPatchBaseline&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --targets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Key=InstanceIds,Values=i-0123456789abcdef0&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --parameters</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Operation=Scan&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 설치 및 재부팅</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aws</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> send-command</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --document-name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;AWS-RunPatchBaseline&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --targets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Key=InstanceIds,Values=i-0123456789abcdef0&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --parameters</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Operation=Install,RebootOption=RebootIfNeeded&quot;</span></span></code></pre></div></div><h3 id="google-chat-웹훅" tabindex="-1">Google Chat 웹훅 <a class="header-anchor" href="#google-chat-웹훅" aria-label="Permalink to “Google Chat 웹훅”">​</a></h3><p><img src="/images/posts/aws-ssm-patch-manager/001.svg" alt="SSM Patch Manager 패치 결과 알림 흐름" loading="lazy"></p><p>AI와 대화를 나누다 보니 정기 패치 내역을 매번 AWS 콘솔에 들어가 확인하는 것도 불편할 것 같다는 이야기가 나왔다. 패치 작업이 끝나면 EventBridge에서 SSM 상태 변경 이벤트를 받아 Lambda를 트리거하고, 적용된 패치 내역과 성공·실패 결과를 Google Chat 웹훅으로 받아보려고 한다.</p><p>월 예상 비용은 약 1달러...?</p>`,33)])}var d=e(c,[[`render`,u]]);export{s as __pageData,d as default};